const newIds=new Set([...PUBL,...POSFIELDS,...COLORS,...STATE].map(v=>v.id)),nodes=figma.currentPage.findAllWithCriteria({types:["FRAME","INSTANCE","RECTANGLE","TEXT","GROUP"]}),changedNodes=[];const positive=allVars.find(v=>v.id==="VariableID:2:42"),negative=allVars.find(v=>v.id==="VariableID:2:46"),neutral=allVars.find(v=>v.id==="VariableID:2:34");const selectorId=byName("Explore/"+lang+"/trader/id").id,posId=byName("Explore/"+lang+"/position/id").id;
function colorAction(role,amount,n){const v=COLORS.find(v=>v.lang===lang&&v.role===role);const token=String(amount).startsWith("−")||String(amount).startsWith("-")?negative:String(amount).startsWith("+")?positive:neutral;return {type:"SET_VARIABLE",variableId:v.id,variableValue:{type:"COLOR",resolvedType:"COLOR",value:token.resolveForConsumer(n).value}}}
function update(as,n,insideProfile){let dirty=false;const hasSelection=(as||[]).some(a=>a.type==="SET_VARIABLE"&&(a.variableId===selectorId||a.variableId===posId||a.variableId==="VariableID:830:2"));const out=[];for(const original of as||[]){if(hasSelection&&original.type==="SET_VARIABLE"&&newIds.has(original.variableId)){dirty=true;continue}const a=JSON.parse(JSON.stringify(original));if(a.type==="CONDITIONAL")for(const block of a.conditionalBlocks){const result=update(block.actions,n,insideProfile);block.actions=result.actions;dirty=dirty||result.dirty}if(a.type==="NODE"&&PROFILE_IDS.includes(a.destinationId)&&!insideProfile&&a.resetScrollPosition!==true){a.resetScrollPosition=true;dirty=true}out.push(a);if(a.type==="SET_VARIABLE"&&a.variableId===selectorId){const trader=TRADERS.find(t=>t.id===a.variableValue.value)||{minimumBudgetCents:null,periods:null};const data=traderValues(trader);out.push(...Object.entries(data).map(([id,v])=>set(id,v)));for(const f of local.filter(f=>f.key==="pnl"))out.push(colorAction("trader/"+f.period,data[f.id],n));const active=trader.id==="trader-01"?eq("VariableID:830:2","active"):{type:"BOOLEAN",resolvedType:"BOOLEAN",value:false};out.push({type:"SET_VARIABLE",variableId:STATE[0].id,variableValue:active},{type:"SET_VARIABLE",variableId:STATE[1].id,variableValue:{type:"EXPRESSION",resolvedType:"BOOLEAN",value:{expressionFunction:"NOT",expressionArguments:[active]}}});dirty=true}
if(a.type==="SET_VARIABLE"&&a.variableId===posId){const pos=DATA.positions.find(p=>p.id===a.variableValue.value);if(pos){const values=positionValues(pos);out.push(...Object.entries(values).map(([id,v])=>set(id,v)));out.push(colorAction("position",values[posfields.find(f=>f.key==="pnl").id],n));dirty=true}}
if(a.type==="SET_VARIABLE"&&a.variableId==="VariableID:830:2"){const active=a.variableValue.value==="active"?eq(selectorId,"trader-01"):{type:"BOOLEAN",resolvedType:"BOOLEAN",value:false};out.push({type:"SET_VARIABLE",variableId:STATE[0].id,variableValue:active},{type:"SET_VARIABLE",variableId:STATE[1].id,variableValue:{type:"EXPRESSION",resolvedType:"BOOLEAN",value:{expressionFunction:"NOT",expressionArguments:[active]}}});dirty=true}
}return{actions:out,dirty}}
for(const n of nodes){if(!n.reactions?.length)continue;let q=n,inside=false;while(q&&q.type!=="PAGE"){if(PROFILE_IDS.includes(q.id)){inside=true;break}q=q.parent}const rx=JSON.parse(JSON.stringify(n.reactions));let dirty=false;for(const reaction of rx){const result=update(reaction.actions,n,inside);reaction.actions=result.actions;dirty=dirty||result.dirty}if(dirty){n.reactions=rx;changedNodes.push(n.id)}}return{mutatedNodeIds:changedNodes,updatedCount:changedNodes.length};

